/* Modo negocio: usa el mismo almacén y sesión de la agenda; no duplica datos. */
(function(global){'use strict';
 global.AgendappxNegocio={crear(ctx){
 const {Store,C,esc,money,today,nowMin,list,byId,svcOf,cliOf,miniaturaServicio,nombreEspecialista,openSheet,closeSheet,navSheet,hora24,toast,render,save,sheetCita}=ctx;
 const $=(s,r=document)=>r.querySelector(s);
 const fila=(titulo,accion,nota='')=>`<button type="button" class="cell" data-negocio="${accion}"><span class="l">${esc(titulo)}${nota?`<small>${esc(nota)}</small>`:''}</span><span class="chev" aria-hidden="true">›</span></button>`;
 let cacheHorarios=null,claveHorarios='',cargando=false;
 const propia=c=>Store.cuenta?.rol!=='especialista'||c.especialista===Store.cuenta.usuarioId;
 const activas=c=>!['cancelada','solicitada'].includes(c.estado);
 const citar=c=>`<button type="button" class="cell" data-cita="${esc(c.id)}">${miniaturaServicio(svcOf(c))}<span class="l"><b>${esc(cliOf(c).nombre)}</b><small>${esc(svcOf(c).nombre)} · ${esc(c.date)} · ${esc(c.start)} · ${esc(nombreEspecialista(c.especialista||'sin-asignar'))}</small><small>${esc(({solicitada:'Solicitud nueva',apartada:'Apartada',pendiente:'Por confirmar',confirmada:'Confirmada',completada:'Completada'})[c.estado]||c.estado)}</small></span><span class="chev" aria-hidden="true">›</span></button>`;
 function hoy(){
  const fecha=today(),citas=list('cita').filter(c=>c.date===fecha&&activas(c)&&propia(c)),solicitudes=list('cita').filter(c=>c.estado==='solicitada'&&propia(c));
  const monto=citas.reduce((n,c)=>n+Number(svcOf(c).precio||0),0),anticipos=citas.filter(c=>c.anticipo&&['pendiente','vencido'].includes(c.anticipo.estado));
  const ingreso=!Store.cuenta||Store.cuenta.rol==='admin'||Store.cuenta.rol==='especialista';
  const tarjetas=[['Citas de hoy',citas.length],...(ingreso?[[Store.cuenta?.rol==='especialista'?'Mi ingreso estimado':'Ingreso estimado',money(monto)]]:[]),['Solicitudes nuevas',solicitudes.length],...(Store.cuenta?.rol==='especialista'?[]:[['Anticipos pendientes',anticipos.length]])];
  const siguientes=citas.filter(c=>c.estado!=='completada'&&C.toMin(c.start)+Number(svcOf(c).duracion||60)>nowMin()).sort((a,b)=>a.start.localeCompare(b.start));
  const lunes=C.addDays(fecha,-((C.weekday(fecha)+6)%7)),semana=list('cita').filter(c=>c.date>=lunes&&c.date<C.addDays(lunes,7)&&activas(c)&&propia(c));
  return `<div class="nav"><span class="scope-name">${esc(Store.settings.negocio)} · Agendappx</span></div><h1 class="big">Hoy</h1><p class="neutral-label">${esc(C.cap(C.DOW[C.weekday(fecha)]))} ${+fecha.slice(8)} de ${esc(C.MES[+fecha.slice(5,7)-1])}</p><div class="hoy-cifras">${tarjetas.map(([n,v])=>`<div><b>${esc(v)}</b><span>${esc(n)}</span></div>`).join('')}</div>
  <h2 class="section-title">Solicitudes desde la app</h2><div class="group">${solicitudes.length?solicitudes.map(c=>`${citar(c)}<div class="request-actions"><button type="button" class="btn fill" data-aceptar="${esc(c.id)}">Aceptar</button><button type="button" class="btn" data-proponer="${esc(c.id)}">Otra hora</button></div>`).join(''):'<p class="empty compact">No tienes solicitudes nuevas.</p>'}</div>
  <h2 class="section-title">Siguen hoy</h2><div class="group">${siguientes.map(citar).join('')||'<p class="empty compact">Tu agenda está libre por hoy.</p>'}</div>
  <h2 class="section-title">Tu semana en Agendappx</h2><div class="group"><div class="cell"><span class="l">Citas de esta semana</span><b>${semana.length}</b></div><div class="cell"><span class="l">Solicitadas desde la app<small>Solo las citas con origen registrado</small></span><b>${semana.filter(c=>['explorar','social'].includes(c.origen)).length}</b></div></div>`;
 }
 function negocio(){const foto=list('servicio').find(s=>typeof s.foto==='string'&&s.foto.startsWith('data:image/jpeg;base64,'))?.foto;
 return `<div class="nav"></div><h1 class="big">Mi negocio</h1><section class="negocio-portada">${foto?`<img src="${esc(foto)}" alt="Trabajo de ${esc(Store.settings.negocio)}">`:'<div class="cover-empty">Tu espacio, tus trabajos</div>'}<div><b>${esc(Store.settings.negocio)}</b><p>Tu salón en Agendappx</p></div></section><div class="profile-actions"><button type="button" class="btn fill" data-negocio="perfil">Ver como cliente</button><a class="btn" href="/comunidad/">Modo cliente</a></div>
 <div class="group">${fila('Servicios y precios','servicios','Catálogo, duración y fotografías')}${fila('Fotos de trabajos','fotos')}${Store.cuenta?.rol==='admin'?fila('Estadísticas','estadisticas','Citas e ingresos de tu salón'):''}${fila('Reseñas','resenas')}${fila('Equipo','equipo')}${fila('Horarios','horarios')}${fila('WhatsApp','whatsapp')}${fila('Conexiones','conexiones','Calendarios y grupos de Facebook')}${fila('Promociones','promos')}${fila('Mi plan','plan')}${fila('Apariencia','apariencia','White y Dark')}</div>`;
 }
 async function api(ruta,opciones={}){const s=await global.AgendappxCuentas?.sesion();if(!s)throw new Error('Inicia sesión para administrar tu salón.');if(s.sinConexion||!navigator.onLine)throw new Error('Conéctate a internet para guardar estos cambios.');const r=await fetch('/api/negocios/'+s.negocioId+'/gestion/'+ruta,{...opciones,headers:{'Content-Type':'application/json',Authorization:'Bearer '+s.accessToken},cache:'no-store',signal:AbortSignal.timeout(12000)});const d=await r.json();const actual=await global.AgendappxCuentas?.sesion();if(!actual||actual.usuarioId!==s.usuarioId||actual.negocioId!==s.negocioId||actual.rol!==s.rol)throw new Error('Tu cuenta cambió. Abre de nuevo esta pantalla.');if(!r.ok)throw new Error(d.error||'No se pudo consultar el salón.');return d;}
 async function cargar(){const cuenta=Store.cuenta;if(!cuenta){cacheHorarios=null;claveHorarios='';return;}const clave=[cuenta.usuarioId,cuenta.negocioId,cuenta.rol,cuenta.aal].join(':');if(clave!==claveHorarios){cacheHorarios=null;claveHorarios=clave;try{const guardado=JSON.parse(localStorage.getItem('agendappx.horarios.'+clave));if(Array.isArray(guardado?.personas)&&Array.isArray(guardado?.especiales))cacheHorarios=guardado;}catch{}}if(cargando||!navigator.onLine)return;cargando=true;try{const datos=await api('horarios');if(claveHorarios!==clave)return;cacheHorarios=datos;try{localStorage.setItem('agendappx.horarios.'+clave,JSON.stringify(datos));}catch{}}catch{}finally{cargando=false;}}
 function personas(servicio){return (cacheHorarios?.personas||[]).filter(p=>(Store.cuenta?.rol!=='especialista'||p.id===Store.cuenta.usuarioId)&&(p.servicios?.includes(servicio)||p.id===Store.cuenta?.usuarioId&&Store.cuenta?.rol==='admin'));}
 function enTurno(fecha,desde,duracion,id){if(!id||!cacheHorarios)return true;const p=cacheHorarios.personas.find(p=>p.id===id);if(!p)return false;const dia=['dom','lun','mar','mie','jue','vie','sab'][C.weekday(fecha)],h=p.horario||{},e=cacheHorarios.especiales.find(e=>e.persona===id&&e.fecha===fecha);let tramo=Object.hasOwn(h,dia)?h[dia]:[Store.settings.abre,Store.settings.cierra];if(e?.tipo==='libre'||!tramo)return false;if(e?.tipo==='horario')tramo=[e.desde,e.hasta];const a=C.toMin(desde),b=a+duracion;return a>=Math.max(C.toMin(tramo[0]),C.toMin(Store.settings.abre))&&b<=Math.min(C.toMin(tramo[1]),C.toMin(Store.settings.cierra))&&(!h.comida||b<=C.toMin(h.comida[0])||a>=C.toMin(h.comida[1]));}
 function hoja(titulo,contenido,montar){openSheet(navSheet(titulo,'Listo')+contenido,titulo,root=>{root.addEventListener('click',e=>{if(e.target.closest('[data-close],[data-done]'))closeSheet();});montar?.(root);});}
 function fotos(){const servicios=list('servicio').filter(s=>typeof s.foto==='string'&&s.foto.startsWith('data:image/jpeg;base64,'));hoja('Fotos de trabajos',`<p class="foot">Fotos que ya guardaste en tus servicios. La publicación en Comunidad se activa con la etapa Social.</p><div class="negocio-fotos">${servicios.map(s=>`<button type="button" data-servicio="${esc(s.id)}"><img src="${esc(s.foto)}" alt="${esc(s.nombre)}"><span>${esc(s.nombre)}</span></button>`).join('')||'<p class="foot">Agrega una foto a un servicio para verla aquí.</p>'}</div>`,root=>root.addEventListener('click',e=>{const b=e.target.closest('[data-servicio]');if(b){closeSheet();ctx.servicio(b.dataset.servicio);}}));}
 async function estadisticas(){hoja('Estadísticas','<p class="foot" role="status" id="negocio-carga">Consultando tu salón…</p>');const root=$('#sheetCard');try{const d=await api('estadisticas');if(!root.isConnected||!$('#negocio-carga',root))return;$('#negocio-carga',root).outerHTML=`<p class="foot">${esc(d.hoy.fecha)} · Las cifras de ingresos son estimadas con los precios actuales.</p><div class="group"><div class="cell"><span class="l">Citas de hoy</span><b>${d.hoy.citas}</b></div><div class="cell"><span class="l">Ingreso estimado de hoy</span><b>${money(d.hoy.ingresosEstimados)}</b></div><div class="cell"><span class="l">Citas completadas hoy</span><b>${d.hoy.completadas}</b></div><div class="cell"><span class="l">Citas este mes</span><b>${d.mes.citas}</b></div><div class="cell"><span class="l">Ingreso estimado del mes</span><b>${money(d.mes.ingresosEstimados)}</b></div></div>`;}catch(e){if(root.isConnected&&$('#negocio-carga',root))$('#negocio-carga',root).textContent=e.message;}}
 async function perfil(){try{const d=await api('resumen');if(global.AgendappxSocial?.perfilNegocio)return global.AgendappxSocial.perfilNegocio(d.perfilUrl);hoja('Perfil público','<p class="foot">El perfil con reservas reales se habilitará en la etapa Explorar. Tu catálogo privado sigue disponible en Servicios y precios.</p>');}catch(e){toast(e.message);}}
 function pendientes(titulo){hoja(titulo,'<p class="foot">Esta función se habilitará al publicar las siguientes etapas. Tus datos actuales se conservan.</p>');}
 function menu(){openSheet(navSheet('Crear','')+`<div class="group">${fila('Nueva cita','nueva-cita')}${fila('Publicar trabajo','publicar')}${fila('Nueva promoción','nueva-promo')}</div>`,'Crear',root=>root.addEventListener('click',e=>{if(e.target.closest('[data-close]'))closeSheet();const b=e.target.closest('[data-negocio]');if(b){closeSheet();accion(b.dataset.negocio);}}));}
 const dias=[['lun','Lunes'],['mar','Martes'],['mie','Miércoles'],['jue','Jueves'],['vie','Viernes'],['sab','Sábado'],['dom','Domingo']];
 async function horarios(){openSheet(navSheet('Horarios','')+'<p class="foot" id="horarios-status" role="status">Consultando horarios…</p>','Horarios',root=>root.addEventListener('click',e=>{if(e.target.closest('[data-close]'))closeSheet();}));const raiz=$('#sheetCard');let d;try{d=await api('horarios');}catch(e){if(raiz.isConnected)$('#horarios-status',raiz).textContent=e.message;return;}if(!raiz.isConnected)return;
 let persona=d.puedeEditarTodas?d.propia:d.propia,especiales=[],h={};
 const disponible=()=>d.puedeEditarTodas||persona===d.propia;
 function dibujar(){const p=d.personas.find(p=>p.id===persona)||d.personas[0];if(!p)return;persona=p.id;h=structuredClone(p.horario||{});especiales=d.especiales.filter(e=>e.persona===persona).map(({fecha,tipo,desde,hasta})=>({fecha,tipo,desde,hasta}));
  raiz.innerHTML='<div class="grab"></div>'+navSheet('Mi horario','Guardar')+`<div class="group"><label class="cell"><span class="l">Persona</span><select id="horario-persona" class="in">${d.personas.map(p=>`<option value="${esc(p.id)}" ${persona===p.id?'selected':''}>${esc(p.nombre)}</option>`).join('')}</select></label></div><p class="foot">Horario de 24 h. Los días apagados son de descanso. Un horario aún sin personalizar usa la apertura y cierre del salón.</p><div class="group">${dias.map(([k,n])=>{const tramo=Object.hasOwn(h,k)?h[k]:[Store.settings.abre,Store.settings.cierra];return `<div class="cell horario-dia"><span class="l">${n}</span><button class="sw" type="button" role="switch" aria-label="Trabaja el ${n.toLowerCase()}" data-dia="${k}" aria-checked="${!!tramo}" ${disponible()?'':'disabled'}></button><div ${tramo?'':'hidden'} data-tramo="${k}">${hora24(tramo?.[0]||'10:00',`data-hora="${k}" data-lado="0"`,n+' desde')}${hora24(tramo?.[1]||'20:00',`data-hora="${k}" data-lado="1"`,n+' hasta')}</div></div>`;}).join('')}</div><p class="gh">Hora de comida</p><div class="group"><div class="cell"><span class="l">Descanso para comer</span><button class="sw" type="button" role="switch" id="horario-comida" aria-label="Hora de comida" aria-checked="${!!h.comida}" ${disponible()?'':'disabled'}></button></div><div class="cell" id="horario-comida-tramo" ${h.comida?'':'hidden'}>${hora24(h.comida?.[0]||'14:00','id="comida-desde"','Comida desde')}${hora24(h.comida?.[1]||'15:00','id="comida-hasta"','Comida hasta')}</div></div><p class="gh">Días especiales</p><div class="group" id="horario-especiales"></div>${disponible()?`<div class="group" style="margin-top:12px"><label class="cell"><span class="l">Fecha</span><input type="date" id="especial-fecha" value="${today()}"></label><label class="cell"><span class="l">Tipo</span><select id="especial-tipo"><option value="libre">Día libre / vacaciones</option><option value="horario">Horario diferente</option></select></label><div class="cell">${hora24('10:00','id="especial-desde"','Horario especial desde')}${hora24('15:00','id="especial-hasta"','Horario especial hasta')}</div><button type="button" class="cell" id="especial-agregar">Agregar día especial</button></div>`:''}<p class="foot" role="status" id="horario-feedback">${disponible()?'Los cambios se guardan al tocar ✓.':'Solo puedes editar tu propio horario.'}</p>`;
  for(const campo of raiz.querySelectorAll('[data-hora],#comida-desde,#comida-hasta'))campo.disabled=!disponible();raiz.querySelector('[data-done]').disabled=!disponible();dibujarEspeciales();
 }
 function dibujarEspeciales(){$('#horario-especiales',raiz).innerHTML=especiales.map((e,j)=>`<div class="cell"><span class="l">${esc(e.fecha)}<small>${e.tipo==='libre'?'Día libre':esc(e.desde)+' – '+esc(e.hasta)}</small></span>${disponible()?`<button class="btn" type="button" data-quitar-especial="${j}" aria-label="Quitar ${esc(e.fecha)}">✕</button>`:''}</div>`).join('')||'<p class="foot">No hay días especiales.</p>';}
 dibujar();raiz.addEventListener('change',e=>{if(e.target.id==='horario-persona'){persona=e.target.value;dibujar();}});let guardando=false;
 raiz.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;if(b.hasAttribute('data-dia')){b.setAttribute('aria-checked',String(b.getAttribute('aria-checked')!=='true'));$('[data-tramo="'+b.dataset.dia+'"]',raiz).hidden=b.getAttribute('aria-checked')!=='true';}if(b.id==='horario-comida'){b.setAttribute('aria-checked',String(b.getAttribute('aria-checked')!=='true'));$('#horario-comida-tramo',raiz).hidden=b.getAttribute('aria-checked')!=='true';}if(b.dataset.quitarEspecial!==undefined){especiales.splice(+b.dataset.quitarEspecial,1);dibujarEspeciales();}if(b.id==='especial-agregar'){const fecha=$('#especial-fecha',raiz).value,tipo=$('#especial-tipo',raiz).value;if(!fecha)return;const e={fecha,tipo,desde:tipo==='horario'?$('#especial-desde',raiz).value:null,hasta:tipo==='horario'?$('#especial-hasta',raiz).value:null};especiales=especiales.filter(x=>x.fecha!==fecha);especiales.push(e);especiales.sort((a,b)=>a.fecha.localeCompare(b.fecha));dibujarEspeciales();}if(b.hasAttribute('data-done')&&!guardando){guardando=true;b.disabled=true;try{const horario={};for(const [k]of dias){horario[k]=$('[data-dia="'+k+'"]',raiz).getAttribute('aria-checked')==='true'?[...raiz.querySelectorAll('[data-hora="'+k+'"]')].map(x=>x.value):null;}horario.comida=$('#horario-comida',raiz).getAttribute('aria-checked')==='true'?[$('#comida-desde',raiz).value,$('#comida-hasta',raiz).value]:null;await api('horario/'+persona,{method:'PUT',body:JSON.stringify({horario,especiales})});await cargar();closeSheet();toast('Horario guardado.');}catch(e){$('#horario-feedback',raiz).textContent=e.message;}finally{guardando=false;b.disabled=false;}}});
 }
 function aceptar(id){const c=byId(id);if(!c||c.estado!=='solicitada')return;openSheet(navSheet('Aceptar solicitud','Aceptar')+`<p class="foot">${esc(cliOf(c).nombre)} · ${esc(svcOf(c).nombre)}<br>${esc(c.date)} a las ${esc(c.start)}.</p><p class="foot">${c.anticipo&&c.anticipo.estado!=='no_aplica'?'Quedará apartada hasta que registres el anticipo.':'Quedará confirmada.'} Los envíos automáticos siguen apagados.</p>`,'Aceptar solicitud',root=>root.addEventListener('click',e=>{if(e.target.closest('[data-close]'))closeSheet();if(e.target.closest('[data-done]')){const actual=byId(id);if(actual?.estado!=='solicitada'){toast('Esta solicitud ya cambió.');return;}if(save({...actual,estado:actual.anticipo&&actual.anticipo.estado!=='no_aplica'&&actual.anticipo.estado!=='recibido'?'apartada':'confirmada'})){closeSheet();render();void Store.sync?.sync();}}}));}
 function accion(a){({servicios:()=>ctx.tab('servicios'),promos:()=>ctx.tab('promos'),apariencia:()=>ctx.tab('apariencia'),conexiones:()=>ctx.tab('conexiones'),equipo:ctx.equipo,whatsapp:ctx.whatsapp,horarios,estadisticas,fotos,perfil,resenas:()=>global.AgendappxSocial?.resenas?global.AgendappxSocial.resenas():pendientes('Reseñas'),plan:()=>global.AgendappxPlanes?.abrir?global.AgendappxPlanes.abrir():pendientes('Mi plan'),'nueva-cita':()=>sheetCita({date:ctx.fecha()}),'nueva-promo':ctx.promo,publicar:()=>global.AgendappxSocial?.publicar?global.AgendappxSocial.publicar():pendientes('Publicar trabajo')})[a]?.();}
 document.addEventListener('click',e=>{const b=e.target.closest('[data-negocio],[data-aceptar],[data-proponer]');if(!b||b.closest('#sheetCard'))return;if(b.dataset.negocio)accion(b.dataset.negocio);else if(b.dataset.aceptar)aceptar(b.dataset.aceptar);else if(b.dataset.proponer)sheetCita({id:b.dataset.proponer,proponer:true});});
 return {hoy,negocio,menu,accion,horarios,cargar,personas,enTurno};
 }};
})(window);
